from PIL import Image
import numpy as np
a=np.array(Image.open('first_frame.png')).astype(float)
# sample specific vertical boundaries at y 70,80,90,100,110,120,130 for x 120..256
for y in [70,75,80,85,90,95,100,105,110,115,120,125,130,135,140]:
 # list runs where brightness crosses 150 and 200
 for t in [120,150,180,210]:
  xs=np.where(a[y].mean(1)>t)[0]
  runs=[]
  if len(xs):
   st=pr=xs[0]
   for x in xs[1:]:
    if x>pr+1:
     if pr-st>=1:runs.append((st,pr))
     st=x
    pr=x
   if pr-st>=1:runs.append((st,pr))
  print(y,t,runs)
 print()
PY"
